function editTool(id){const t=state.tools.find(x=>x.id===id);if(!t)return;$('toolId').value=t.id;$('toolBrand').value=t.brand||'';$('toolLabel').value=t.label||'';$('toolName').value=t.name||'';const matchedCategory=t.categoryId||state.categories.find(c=>String(c.name||'').toLowerCase()===String(t.categoryName||t.category||'').toLowerCase())?.id||'';$('toolCategory').value=matchedCategory;$('toolModel').value=t.model||'';$('toolSerial').value=t.serial||'';$('toolStatus').value=t.status||'Available';$('toolLocation').value=t.locationId||'';$('purchaseDate').value=t.purchaseDate||'';$('warrantyExpiry').value=t.warrantyExpiry||'';$('lastVerified').value=t.lastVerified||'';$('photoReminderMonths').value=String(t.photoReminderMonths??6);$('manufacturerPhotoURL').value=t.manufacturerPhotoURL||'';$('privateTool').checked=!!t.privateTool;$('toolNotes').value=t.notes||'';$('toolPhoto').value='';if($('manufacturerPhotoFile'))$('manufacturerPhotoFile').value='';$('toolModalTitle').textContent='Edit tool';updateLabelSuggestion();showDuplicateWarning();openModal('toolModal')}
function viewTool(id){
  const t=state.tools.find(x=>x.id===id);if(!t||(!isAdmin()&&t.privateTool))return;
  const cat=t.categoryName||t.category||'Uncategorized',w=warrantyState(t.warrantyExpiry);const photos=[];
  if(t.manufacturerPhotoURL)photos.push(`<button class="detail-photo-wrap photo-button" type="button" data-preview-image="${esc(t.manufacturerPhotoURL)}" data-preview-title="Manufacturer / Primary"><img class="detail-photo" src="${esc(t.manufacturerPhotoURL)}" alt="Manufacturer photo"><span class="photo-slot-label">Manufacturer / Primary</span><small>Tap to enlarge</small></button>`);
  if(t.photoURL)photos.push(`<button class="detail-photo-wrap photo-button" type="button" data-preview-image="${esc(t.photoURL)}" data-preview-title="Our Tool"><img class="detail-photo" src="${esc(t.photoURL)}" alt="Actual tool photo"><span class="photo-slot-label">Our Tool</span><small>Tap to enlarge</small></button>`);
  const hist=state.history.filter(h=>h.toolId===id).slice(0,10);
  $('detailTitle').textContent=`${t.label||''} · ${t.name||'Tool'}`;
  $('toolDetailBody').innerHTML=`<div class="detail-hero"><div class="detail-photo-grid">${photos.length?photos.join(''):`<div class="tool-placeholder" style="width:100%;min-height:180px">${icon('tools')}</div>`}</div><div><div class="card-actions"><span class="badge ${slugStatus(t.status)}">${esc(t.status||'Available')}</span>${t.privateTool?'<span class="badge">Private</span>':''}</div><h2>${esc(t.name||'Unnamed tool')}</h2><p class="muted">${esc(t.brand||'')} ${esc(t.model||'')}</p><div class="detail-data"><div><span>Label</span><strong>${esc(t.label||'—')}</strong></div><div><span>Location</span><strong>${esc(t.locationName||'Unassigned')}</strong></div><div><span>Category</span><strong>${esc(cat)}</strong></div><div><span>Serial</span><strong>${esc(t.serial||'—')}</strong></div><div><span>Purchased</span><strong>${formatDateOnly(t.purchaseDate)}</strong></div><div><span>Warranty</span><strong>${t.warrantyExpiry?`${formatDateOnly(t.warrantyExpiry)}${w?` · ${w.label}`:''}`:'—'}</strong></div></div><p>${esc(t.notes||'')}</p><div class="card-actions"><button class="btn accent" data-move-tool="${t.id}">Move / status</button><button class="btn" data-edit-tool="${t.id}">Edit Tool</button></div></div></div><hr style="border:0;border-top:1px solid var(--line);margin:18px 0"><h3>Recent history</h3><div class="timeline">${hist.length?hist.map(historyHTML).join(''):'<div class="empty">No history yet.</div>'}</div>`;
  openModal('toolDetailModal')
}
function previewImage(url,title='Tool photo'){$('imagePreviewImg').src=url;$('imagePreviewTitle').textContent=title;openModal('imagePreviewModal')}

function moveTool(id){const t=state.tools.find(x=>x.id===id);if(!t)return;$('moveToolId').value=id;$('moveStatus').value=t.status||'Available';$('moveLocation').value=t.locationId||'';$('moveNote').value='';openModal('moveModal')}
async function writeHistory(tool,action,note=''){await addDoc(collection(db,'history'),{toolId:tool.id||'',toolLabel:tool.label||'',toolName:tool.name||'',action,note,actorUid:state.user.uid,actorName:displayName(),createdAt:serverTimestamp()})}
async function saveTool(e){e.preventDefault();const id=$('toolId').value.trim(),location=currentLocation($('toolLocation').value);if(!location)return toast('Choose a location first.',true);const duplicate=state.tools.find(t=>String(t.label||'').trim().toLowerCase()===$('toolLabel').value.trim().toLowerCase()&&t.id!==id);if(duplicate)return toast('That tool label is already in use.',true);const category=currentCategory($('toolCategory').value);const payload={label:$('toolLabel').value.trim(),name:$('toolName').value.trim(),brand:$('toolBrand').value.trim(),model:$('toolModel').value.trim(),categoryId:category?.id||'',categoryName:category?.name||'',category:category?.name||'',serial:$('toolSerial').value.trim(),status:$('toolStatus').value,locationId:location.id,locationName:location.name,purchaseDate:$('purchaseDate').value,warrantyExpiry:$('warrantyExpiry').value,lastVerified:$('lastVerified').value,photoReminderMonths:Number($('photoReminderMonths').value||6),manufacturerPhotoURL:$('manufacturerPhotoURL').value.trim(),privateTool:isAdmin()&&$('privateTool').checked,notes:$('toolNotes').value.trim(),updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName()};const btn=$('saveToolBtn');btn.disabled=true;btn.textContent='Saving…';try{let toolRef,existing=id?state.tools.find(t=>t.id===id):null;if(id){toolRef=doc(db,'tools',id);await updateDoc(toolRef,payload)}else toolRef=await addDoc(collection(db,'tools'),{...payload,createdAt:serverTimestamp(),createdBy:state.user.uid});const manufacturerFile=$('manufacturerPhotoFile')?.files?.[0];if(manufacturerFile){if(manufacturerFile.size>8*1024*1024)throw new Error('Manufacturer image is over 8 MB.');const safe=manufacturerFile.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`tool-photos/${toolRef.id}/manufacturer-${Date.now()}-${safe}`;const sr=ref(storage,path);await uploadBytes(sr,manufacturerFile,{contentType:manufacturerFile.type});const manufacturerPhotoURL=await getDownloadURL(sr);await updateDoc(toolRef,{manufacturerPhotoURL,manufacturerPhotoPath:path,updatedAt:serverTimestamp()});payload.manufacturerPhotoURL=manufacturerPhotoURL}const photo=$('toolPhoto').files?.[0];if(photo){if(photo.size>8*1024*1024)throw new Error('Photo is over 8 MB.');const safe=photo.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=`tool-photos/${toolRef.id}/${Date.now()}-${safe}`;const sr=ref(storage,path);await uploadBytes(sr,photo,{contentType:photo.type});const photoURL=await getDownloadURL(sr);await updateDoc(toolRef,{photoURL,photoPath:path,conditionPhotoAt:new Date().toISOString().slice(0,10),updatedAt:serverTimestamp()});payload.photoURL=photoURL}await writeHistory({id:toolRef.id,...payload},id?'Tool details updated':'Tool added',existing?`Previous location: ${existing.locationName||'Unassigned'}`:'');closeModal('toolModal');toast(id?'Tool updated.':'Tool added.')}catch(err){console.error(err);toast(err.message||'Could not save tool.',true)}finally{btn.disabled=false;btn.textContent='Save tool'}}
async function saveMove(e){e.preventDefault();const id=$('moveToolId').value,tool=state.tools.find(t=>t.id===id),location=currentLocation($('moveLocation').value);if(!tool||!location)return;const oldStatus=tool.status||'Available',oldLocation=tool.locationName||'Unassigned',status=$('moveStatus').value,note=$('moveNote').value.trim();try{await updateDoc(doc(db,'tools',id),{status,locationId:location.id,locationName:location.name,assignedToUid:status==='In Use'?state.user.uid:'',assignedToName:status==='In Use'?displayName():'',updatedAt:serverTimestamp(),updatedBy:state.user.uid,updatedByName:displayName(),lastVerified:new Date().toISOString().slice(0,10)});await writeHistory(tool,`${oldStatus} @ ${oldLocation} → ${status} @ ${location.name}`,note);closeModal('moveModal');closeModal('toolDetailModal');toast('Tool updated.')}catch(err){toast(err.message,true)}}

async function reconcileJobLocations(){
  if(!isAdmin())return;
  for(const j of state.jobs){
    if(state.syncingJobLocations.has(j.id))continue;
    const linked=state.locations.find(l=>l.jobId===j.id);
    const shouldActive=j.status!=='Completed';
    const desired={name:j.name||'Jobsite',type:'Jobsite',jobId:j.id,active:shouldActive,updatedAt:serverTimestamp(),updatedBy:state.user.uid};
    try{
      state.syncingJobLocations.add(j.id);
      if(!linked&&shouldActive)await addDoc(collection(db,'locations'),{...desired,createdAt:serverTimestamp()});
      else if(linked&&(linked.name!==desired.name||linked.type!=='Jobsite'||linked.active!==shouldActive))await updateDoc(doc(db,'locations',linked.id),desired);
    }catch(err){console.error('Jobsite location sync failed',j.id,err)}finally{state.syncingJobLocations.delete(j.id)}
  }
}


