function fillCloseoutJobs(){if(!$('closeoutJobSelect'))return;const rows=state.jobs.filter(j=>j.status==='Active').sort((a,b)=>String(a.name||'').localeCompare(String(b.name||'')));$('closeoutJobSelect').innerHTML=rows.map(j=>`<option value="${esc(j.id)}">${esc(j.name)}</option>`).join('')||'<option value="">No active jobs</option>'}
function loadCloseout(){const id=$('closeoutJobSelect').value,j=currentJob(id);if(!j)return;$('closeoutBody').dataset.jobId=id;const ids=new Set(state.locations.filter(l=>l.jobId===id).map(l=>l.id)),tools=visibleTools().filter(t=>ids.has(t.locationId));$('closeoutBody').innerHTML=tools.length?`<div class="closeout-summary"><strong>${tools.length} tool${tools.length===1?'':'s'} still assigned to ${esc(j.name)}</strong><span>Verify each tool, then move it to Shop/Storage or another active job.</span></div><div class="closeout-list">${tools.map(t=>`<div class="closeout-row"><div><strong>${esc(t.label||'—')} · ${esc(t.name||'Tool')}</strong><small>${esc(t.status||'Available')} · last verified ${t.lastVerified?formatDateOnly(t.lastVerified):'never'}</small></div><button class="btn accent smallbtn" data-closeout-move="${t.id}">Move</button></div>`).join('')}</div><button class="btn primary wide" data-finish-closeout="${id}">Finish closeout when empty</button>`:`<div class="closeout-summary ready"><strong>All clear.</strong><span>No tools remain assigned to this job.</span></div><button class="btn accent wide" data-finish-closeout="${id}">Mark job completed</button>`}
async function finishCloseout(id){if(!isAdmin())return;const ids=new Set(state.locations.filter(l=>l.jobId===id).map(l=>l.id)),remaining=visibleTools().filter(t=>ids.has(t.locationId));if(remaining.length)return toast(`${remaining.length} tool${remaining.length===1?' is':'s are'} still assigned to this job.`,true);try{await updateDoc(doc(db,'jobs',id),{status:'Completed',closedAt:serverTimestamp(),closedBy:state.user.uid,updatedAt:serverTimestamp()});for(const l of state.locations.filter(l=>l.jobId===id))await updateDoc(doc(db,'locations',l.id),{active:false,updatedAt:serverTimestamp()});closeModal('closeoutModal');toast('Job closed out. Nothing left behind.')}catch(err){toast(err.message,true)}}

