function editJob(id){const j=state.jobs.find(x=>x.id===id);if(!j)return;$('jobId').value=id;$('jobName').value=j.name||'';$('jobStatus').value=j.status||'Active';$('jobAddress').value=j.address||'';$('jobContact').value=j.contact||'';$('jobPhone').value=j.phone||'';$('jobNotes').value=j.notes||'';$('jobModalTitle').textContent='Edit job';openModal('jobModal')}
async function saveJob(e){e.preventDefault();if(!isAdmin())return;const id=$('jobId').value,payload={name:$('jobName').value.trim(),status:$('jobStatus').value,address:$('jobAddress').value.trim(),contact:$('jobContact').value.trim(),phone:$('jobPhone').value.trim(),notes:$('jobNotes').value.trim(),updatedAt:serverTimestamp(),updatedBy:state.user.uid};try{let jobId=id;if(id)await updateDoc(doc(db,'jobs',id),payload);else{const r=await addDoc(collection(db,'jobs'),{...payload,createdAt:serverTimestamp()});jobId=r.id}const linked=state.locations.find(l=>l.jobId===jobId);const locPayload={name:payload.name,type:'Jobsite',jobId,active:payload.status!=='Completed',updatedAt:serverTimestamp(),updatedBy:state.user.uid};if(linked)await updateDoc(doc(db,'locations',linked.id),locPayload);else if(payload.status!=='Completed')await addDoc(collection(db,'locations'),{...locPayload,createdAt:serverTimestamp()});closeModal('jobModal');toast(payload.status==='Completed'?'Job saved; jobsite hidden from active locations.':'Job saved and added to tool locations.')}catch(err){toast(err.message,true)}}
